></div>\n\t\t<div id=\"sh\"></div>\n\t</div>\n\t<div id=\"ob\" data-testid=\"outliner\"></div>\n\t<div id=\"dlg\" style=\"display:none;\" data-testid=\"dialog\"></div>\n\t<div id=\"agent-settings-modal\" data-testid=\"agent-settings-modal\" role=\"dialog\" aria-label=\"Agent Settings \u2014 API Providers, MCP &amp; Skills\">\n\t\t<div class=\"agent-settings-dialog\">\n\t\t\t<div class=\"agent-settings-header\">\n\t\t\t\t<div style=\"display:flex;align-items:center;gap:8px;font-weight:600;font-size:15px\">\n\t\t\t\t\t<span style=\"width:8px;height:8px;border-radius:50%;background:#2EE6B6\"></span>\n\t\t\t\t\t<span>Agent Settings</span>\n\t\t\t\t</div>\n\t\t\t\t<div class=\"agent-settings-tabs\">\n\t\t\t\t\t<button type=\"button\" class=\"agent-stab on\" data-agent-stab=\"providers\" data-testid=\"stab-providers\">API Providers (<span id=\"stab-prov-count\">12</span>)</button>\n\t\t\t\t\t<button type=\"button\" class=\"agent-stab\" data-agent-stab=\"mcp\" data-testid=\"stab-mcp\">MCP (<span id=\"stab-mcp-count\">5</span>)</button>\n\t\t\t\t\t<button type=\"button\" class=\"agent-stab\" data-agent-stab=\"skills\" data-testid=\"stab-skills\">Skills (<span id=\"stab-skill-count\">6</span>)</button>\n\t\t\t\t</div>\n\t\t\t\t<button type=\"button\" id=\"agent-settings-close\" class=\"prov-mini-btn\" data-testid=\"agent-settings-close\" aria-label=\"Close settings\">\n\t\t\t\t\t<svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><path d=\"M6 6l12 12M18 6L6 18\"/></svg>\n\t\t\t\t</button>\n\t\t\t</div>\n\t\t\t<div id=\"agent-settings-controls\" class=\"agent-settings-controls\"></div>\n\t\t\t<div id=\"agent-settings-body\" class=\"agent-settings-body\"></div>\n\t\t</div>\n\t</div>\n\t\n\t<!-- Pro Studio Home / Project Hub Overlay -->\n\t<div id=\"studio-home-overlay\" class=\"open\" data-testid=\"studio-home-overlay\" data-document-role=\"page\" data-label=\"Landing\">\n\t\t<div class=\"landing-page-scroll\">\n\t\t\t<div style=\"min-height:100%;background:#0d0f14;color:#cfd5e0;font-family:Inter,system-ui,sans-serif\">\n\t\t\t\t<header style=\"max-width:1100px;margin:0 auto;padding:0 24px;height:72px;display:flex;align-items:center;justify-content:space-between\">\n\t\t\t\t\t<div style=\"display:flex;align-items:center;gap:10px;font-family:Sora,Inter,sans-serif;font-weight:700;font-size:18px;color:#eef1f6\">\n\t\t\t\t\t\t<span style=\"color:#3ddbb0\">\n\t\t\t\t\t\t\t<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\" style=\"width:26px;height:26px;fill:none;stroke:currentColor;stroke-width:1.9;stroke-linecap:round;stroke-linejoin:round;display:block\">\n\t\t\t\t\t\t\t\t<path d=\"M12 3l8 4.5v9L12 21l-8-4.5v-9zM12 12l8-4.5M12 12v9M12 12L4 7.5\"></path>\n\t\t\t\t\t\t\t</svg>\n\t\t\t\t\t\t</span>\n\t\t\t\t\t\tToon Studio 3D\n\t\t\t\t\t</div>\n\t\t\t\t\t<span style=\"font-family:'JetBrains Mono',ui-monospace,monospace;font-size:12px;color:#9aa3b2\">60 fps \u00b7 WASM</span>\n\t\t\t\t</header>\n\n\t\t\t\t<main style=\"max-width:1100px;margin:0 auto;padding:clamp(24px,5vw,56px) 24px 72px\">\n\t\t\t\t\t<h1 style=\"font-family:Sora,Inter,sans-serif;font-weight:700;font-size:clamp(34px,5vw,56px);line-height:1.05;letter-spacing:-.035em;margin:0;color:#eef1f6\">Start a 3D project.</h1>\n\t\t\t\t\t<p style=\"font-size:18px;line-height:1.6;color:#9aa3b2;margin:14px 0 0;max-width:520px\">Create a blank scene or import one. Animate it on a timeline that runs up to one hour.</p>\n\n\t\t\t\t\t<div style=\"display:flex;flex-wrap:wrap;gap:12px;margin-top:30px\">\n\t\t\t\t\t\t<a href=\"#create-project\" id=\"sh-quick-new\" data-testid=\"landing-create-project\" style=\"display:inline-flex;align-items:center;gap:10px;height:52px;padding:0 26px;border-radius:14px;font-weight:600;font-size:16px;background:#3ddbb0;color:#06231D;border:none;text-decoration:none;cursor:pointer\">\n\t\t\t\t\t\t\t<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\" style=\"width:20px;height:20px;fill:none;st