save-current-btn\" style=\"font-family:'JetBrains Mono',ui-monospace,monospace;font-size:12px;color:#3ddbb0;background:transparent;border:none;cursor:pointer\">+ Save current scene</button>\n\t\t\t\t\t\t</div>\n\t\t\t\t\t\t<div id=\"sh-proj-grid\" style=\"display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,440px),1fr));gap:16px\"></div>\n\t\t\t\t\t</div>\n\t\t\t\t</main>\n\t\t\t</div>\n\t\t</div>\n\t</div>\n\n\t<div id=\"msg\" style=\"display:none;\" role=\"alert\"></div>\n";

